import app from "@/store/app";
import { PluginInfo, pluginExtrainfoDefaultValue } from "@/types/plugin";
import ajax from "@/utils/ajax";
import { action, observable, makeObservable } from "mobx";
import React from "react";

class Store {
    @observable list: PluginInfo[] = [];
    @action
    setList = (data) => {
        this.list = data;
    }

    isReady = false;

    init = () => {
        if(this.isReady) return;
        this.isReady = true;
        this.getPlugins();
    }

    getPlugins = () => {
        return ajax.post('/apijson/get', {
            [`PluginProject[]`]: {
                "join": "&/Plugins",
                'PluginProject': {
                    projectId: app.info.projectId,
                },
                "Plugins": {
                    "isActive": 1,
                    "@order": "sort+",
                    "id@": "/PluginProject/pluginId",
                    "@column": "name,description,author,releaseVersion,extraInfo"
                },
                "PluginVersion[]": {
                    count: 0,
                    PluginVersion: {
                        "isReleased": 1,
                        "pluginId@": "PluginProject[]/PluginProject/pluginId",
                        "@column": "versionNumber,pluginId,description",
                        "@order": "versionNumber-"
                    }
                }
            }
        }).then((res) => {
            this.setList(res.PluginProject.map((o) => {
                return {
                    ...o,
                    extraInfo: o.extraInfo? JSON.parse(o.extraInfo) : pluginExtrainfoDefaultValue,
                    PluginVersion: o.PluginVersion.map((o) => {
                        return {
                            ...o,
                            value: o.versionNumber,
                            label: o.versionNumber
                        }
                    })
                }
            }));
            return this.list;
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store();